      "role": "editorial",
      "goal": "Keep members, supporters, and prospective members informed and engaged with club news, coaching updates, player achievements, and event announcements.",
      "meta_description": "The latest news from Courtside & Crown Tennis Academy \u2014 match reports, coaching updates, player achievements, events, and club announcements.",
      "sections": [
        {
          "id": "news-section-1",
          "type": "page_header",
          "intent": "Welcome visitors to the news section and set an editorial, club-magazine tone that feels both authoritative and warm.",
          "eyebrow": "The Courtside Chronicle",
          "headline": "News, Stories & Dispatches from the Club",
          "subheadline": "The latest from our courts, our coaches, and our community \u2014 told with the care this club deserves.",
          "body": null,
          "items": [],
          "ctas": [],
          "asset_ideas": [
            {
              "id": "news-section-1-asset-1",
              "kind": "illustration",
              "subject": "A vintage newspaper masthead-style banner reading 'The Courtside Chronicle' with a small tennis racket and laurel ornament, in the style of a 1930s sporting gazette.",
